def _env(*names):
    for n in names:
        v = os.environ.get(n)
        if v and v.strip():
            return v.strip()
    return ''


def load_ai_config():
    """合并 config.json / 环境变量 / 文件内常量，返回 (ready, base_url, key, model)。"""
    enabled, base_url = AI_ENABLED, AI_BASE_URL
    api_key, model = AI_API_KEY, AI_MODEL

    cfg_path = os.path.join(BASE_DIR, 'config.json')
    if os.path.isfile(cfg_path):
        try:
            cfg = json.load(open(cfg_path, encoding='utf-8'))
            enabled = bool(cfg.get('enabled', enabled))
            base_url = (cfg.get('base_url') or base_url).strip()
            api_key = (cfg.get('api_key') or api_key).strip()
            model = (cfg.get('model') or model).strip()
        except Exception as e:
            print('config.json 读取失败：%s' % e)

    base_url = _env('NAIWA_BASE_URL', 'OPENAI_BASE_URL') or base_url
    api_key = _env('NAIWA_API_KEY', 'OPENAI_API_KEY') or api_key
    model = _env('NAIWA_MODEL', 'OPENAI_MODEL') or model

    local = ('localhost' in base_url) or ('127.0.0.1' in base_url)
    ready = bool(enabled and base_url and model and (api_key or local))
    return ready, base_url, api_key, model


AI_READY, AI_BASE_URL, AI_API_KEY, AI_MODEL = load_ai_config()


def ai_chat(history, base_url=None, api_key=None, model=None, timeout=None):
    """调用 OpenAI 兼容的 /chat/completions，返回奶蛙的回复文字。失败会抛异常。
    不传参数就用当前生效的全局配置（界面里保存后会更新它们）。"""
    url = (base_url or AI_BASE_URL).rstrip('/') + '/chat/completions'
    key = AI_API_KEY if api_key is None else api_key
    payload = {
        'model': model or AI_MODEL,
        'messages': [{'role': 'system', 'content': SYSTEM_PROMPT}] + history[-AI_HISTORY:],
        'temperature': AI_TEMPERATURE,
        'max_tokens': AI_MAX_TOKENS,
        'stream': False,
    }
    headers = {'Content-Type': 'application/json'}
    if key:
        headers['Authorization'] = 'Bearer ' + key
    req = urllib.request.Request(url, data=json.dumps(payload).encode('utf-8'),
                                 headers=headers, method='POST')
    with urllib.request.urlopen(req, timeout=timeout or AI_TIMEOUT) as resp:
        obj = json.loads(resp.read().decode('utf-8', 'ignore'))
    return (obj['choices'][0]['message']['content'] or '').strip()


