CONFIG_PATH = os.path.join(BASE_DIR, 'config.json')


def reload_ai_config():
    """重新读取配置（界面保存后 / 手改 config.json 后调用）。"""
    global AI_READY, AI_BASE_URL, AI_API_KEY, AI_MODEL
    AI_READY, AI_BASE_URL, AI_API_KEY, AI_MODEL = load_ai_config()
    return AI_READY


def save_ai_config(base_url, api_key, model, enabled=True):
    """把配置写进同目录 config.json 并立即热重载，返回 (ok, 错误信息)。"""
    try:
        with open(CONFIG_PATH, 'w', encoding='utf-8') as f:
            json.dump({'enabled': bool(enabled), 'base_url': base_url,
                       'api_key': api_key, 'model': model},
                      f, ensure_ascii=False, indent=2)
    except Exception as e:
        return False, str(e)
    reload_ai_config()
    return True, ''


def test_ai(base_url, api_key, model, timeout=15):
    """用给定参数试调一次，返回 (ok, 文案)。"""
    try:
        reply = ai_chat([{'role': 'user', 'content': '用不超过10个字打个招呼'}],
                        base_url=base_url, api_key=api_key, model=model, timeout=timeout)
        return True, reply or '（对方返回了空内容）'
    except urllib.error.HTTPError as e:
        body = ''
        try:
            body = e.read().decode('utf-8', 'ignore')[:180]
        except Exception:
            pass
        return False, 'HTTP %s %s %s' % (e.code, e.reason, body)
    except Exception as e:
        return False, str(e)


