def _materialize(name, data):
    """把 wav 字节写进临时文件，返回文件路径。
    必须走文件：winsound 不允许 SND_MEMORY | SND_ASYNC（会抛
    RuntimeError: Cannot play asynchronously from memory）。"""
    if not data:
        return None
    try:
        os.makedirs(TEMP_SND_DIR, exist_ok=True)
        p = os.path.join(TEMP_SND_DIR, name)
        if (not os.path.isfile(p)) or os.path.getsize(p) != len(data):
            with open(p, 'wb') as f:
                f.write(data)
        return p
    except Exception:
        return None


def _load_sound(filename, b64):
    """返回可播放的 wav 文件路径：优先 sounds/ 里的外部文件，否则用内嵌数据落盘。"""
    p = os.path.join(SOUND_DIR, filename)
    if os.path.isfile(p):
        try:
            with open(p, 'rb') as f:
                if f.read(4) == b'RIFF':
                    return p
        except Exception:
            pass
    try:
        data = base64.b64decode(b64)
    except Exception:
        return None
    if data[:4] != b'RIFF':
        return None
    return _materialize(filename, data)


SOUND_LAUGH = _load_sound('laugh.wav', LAUGH_B64)
SOUND_CUTE = [_load_sound('cute%d.wav' % i, CUTE_B64[i]) for i in range(len(CUTE_B64))]
SOUND_CUTE = [s for s in SOUND_CUTE if s]
SOUND_SONG = _load_sound('song.wav', SONG_B64)


def _winsound():
    try:
        import winsound
        return winsound
    except Exception:
        return None


def play_sound(path, enabled=True):
    """异步播放 wav 文件（不阻塞界面）。"""
    if not path or not enabled:
        return
    ws = _winsound()
    if ws is None:
        return
    try:
        ws.PlaySound(path, ws.SND_FILENAME | ws.SND_ASYNC)
        return
    except Exception:
        pass
    # 兜底：万一异步不行，就在后台线程里同步播，至少不卡界面
    try:
        threading.Thread(target=lambda: ws.PlaySound(path, ws.SND_FILENAME),
                         daemon=True).start()
    except Exception:
        pass


