_last_reply = {}


def frog_reply(text):
    """根据用户输入挑一句奶蛙的回复（简单的关键词匹配 + 随机）。"""
    t = (text or '').lower()
    cat = None
    for name, words in KEYWORDS:
        if any(w in t for w in words):
            cat = name
            break
    if cat is None:
        cat = 'default'
    pool = REPLIES.get(cat) or REPLIES['default']
    prev = _last_reply.get(cat)
    choice = random.choice(pool)
    for _ in range(6):
        if choice != prev or len(pool) == 1:
            break
        choice = random.choice(pool)
    _last_reply[cat] = choice
    return choice


# ============================================================
#  五、绘图小工具
# ============================================================
def round_rect(cv, x1, y1, x2, y2, r, **kw):
    """在 canvas 上画圆角矩形（用平滑多边形近似）。"""
    pts = [x1 + r, y1, x2 - r, y1, x2, y1, x2, y1 + r, x2, y2 - r, x2, y2,
           x2 - r, y2, x1 + r, y2, x1, y2, x1, y2 - r, x1, y1 + r, x1, y1]
    return cv.create_polygon(pts, smooth=True, **kw)


# ============================================================
#  六、AI 设置面板（聊天框里点齿轮打开，不用改任何文件）
# ============================================================
class SettingsBox:
    W, H = 410, 360

    def __init__(self, pet, on_saved=None):
        self.pet = pet
        self.on_saved = on_saved
        self.q = queue.Queue()
        self.busy = False
        self.alive = True
        self._drag = None

        self.win = tk.Toplevel(pet.root)
        self.win.overrideredirect(True)
        self.win.attributes('-topmost', True)
        self.win.configure(bg=TRANSPARENT)
        self.win.attributes('-transparentcolor', TRANSPARENT)
        self.cv = tk.Canvas(self.win, width=self.W, height=self.H,
                            bg=TRANSPARENT, highlightthickness=0)
        self.cv.pack()

        self._draw()
        self._build()
        self._place()
        self._load_current()

    # ---------- 外观 ----------
    def _draw(self):
        cv = self.cv
        round_rect(cv, 6, 6, self.W - 6, self.H - 6, 18,
                   fill=C_PANEL, outline=C_PANEL_EDGE, width=2)
        round_rect(cv, 8, 8, self.W - 8, 54, 15, fill=C_HEAD, outline='')
        cv.create_rectangle(8, 38, self.W - 8, 56, fill=C_HEAD, outline='')
        cv.create_line(10, 56, self.W - 10, 56, fill=C_PANEL_EDGE)
        cv.create_text(22, 32, text='AI 设置', anchor='w',
                       font=('Microsoft YaHei', 12, 'bold'), fill=C_TXT)
        cv.create_oval(self.W - 48, 18, self.W - 20, 44,
                       fill='#FFC9C9', outline='#EFA0A0', tags='close')
        cv.create_text(self.W - 34, 31, text='×', fill='#8A3B3B',
                       font=('Microsoft YaHei', 12, 'bold'), tags='close')
        cv.tag_bind('close', '<Button-1>', lambda e: self.close())
        cv.bind('<Button-1>', self._press)
        cv.bind('<B1-Motion>', self._dragmove)

        lab = ('Microsoft YaHei', 9)
        for i, t in enumerate(('服务商', '接口地址', '模型', 'API Key')):
            cv.create_text(22, 76 + i * 36, text=t, anchor='w', font=lab, fill=C_TXT)
        self.status_item = cv.create_text(22, self.H - 54, text='', anchor='nw',
                                          font=('Microsoft YaHei', 9), fill=C_SUB,
                                          width=self.W - 44)

    def _entry(self, x, y, w):
        e = tk.Entry(self.win, bd=0, highlightthickness=1,
                     highlightbackground=C_PANEL_EDGE, highlightcolor=C_PANEL_EDGE,
                     bg='#FFFFFF', fg=C_TXT, insertbackground=C_TXT,
                     font=('Microsoft YaHei', 9))
        e.place(x=x, y=y, width=w, height=26)
        return e

    def _build(self):
        f = ('Microsoft YaHei', 9)
        btn = dict(bd=0, relief='flat', highlightthickness=0, fg=C_TXT, font=f)

        # 服务商下拉
        self.var_provider = tk.StringVar(value=PROVIDERS[0][0])
        om = tk.OptionMenu(self.win, self.var_provider, *[p[0] for p in PROVIDERS],
                           command=self._on_provider)
        om.config(bg='#FFFFFF', activebackground=C_BTN, bd=0, highlightthickness=1,
                  highlightbackground=C_PANEL_EDGE, font=f, anchor='w')
        om['menu'].config(font=f, bg='#FFFFFF', fg=C_TXT)
        om.place(x=92, y=64, width=self.W - 116, height=26)

        self.e_url = self._entry(92, 100, self.W - 116)
        self.e_model = self._entry(92, 136, self.W - 116)
        self.e_key = self._entry(92, 172, self.W - 116 - 48)
        self.e_key.config(show='●')

        self.btn_show = tk.Button(self.win, text='显示', command=self._toggle_show,
                                  bg='#EFE3C8', activebackground=C_BTN, **btn)
        self.btn_show.place(x=self.W - 24 - 44, y=172, width=44, height=26)

        self.cv.create_text(92, 206, anchor='w', font=('Microsoft YaHei', 8), fill=C_SUB,
                            text='DeepSeek 的 Key 在 platform.deepseek.com 免费注册后创建，形如 sk-…')

        y = self.H - 100
        self.btn_test = tk.Button(self.win, text='测试连接', command=self._test,
                                  bg=C_BTN, activebackground=C_BTN_ACT, **btn)
        self.btn_test.place(x=22, y=y, width=112, height=32)
        self.btn_save = tk.Button(self.win, text='保存并连接', command=self._save,
                                  bg='#A8E6A3', activebackground='#8FD98A', **btn)
        self.btn_save.place(x=146, y=y, width=124, height=32)
        self.btn_off = tk.Button(self.win, text='关闭 AI', command=self._disable,
                                 bg='#EFE3C8', activebackground=C_BTN, **btn)
        self.btn_off.place(x=282, y=y, width=106, height=32)

    def _place(self):
        sw, sh = self.pet.root.winfo_screenwidth(), self.pet.root.winfo_screenheight()
        if self.pet.chat is not None:
            x = self.pet.chat.win.winfo_x() + 20
            y = self.pet.chat.win.winfo_y() + 60
        else:
            x, y = sw - self.W - 80, sh - self.H - 120
        x = min(max(x, 8), sw - self.W - 8)
        y = min(max(y, 8), sh - self.H - 8)
        self.win.geometry('%dx%d+%d+%d' % (self.W, self.H, int(x), int(y)))

    def _load_current(self):
        for name, url, model in PROVIDERS:
            if url and url == AI_BASE_URL:
                self.var_provider.set(name)
                break
        self.e_url.insert(0, AI_BASE_URL or '')
        self.e_model.insert(0, AI_MODEL or '')
        self.e_key.insert(0, AI_API_KEY or '')
        self._status('当前：%s' % ('已连接' if AI_READY else '未连接（缺 API Key）'),
                     '#2E8B57' if AI_READY else C_SUB)

    # ---------- 拖动 ----------
    def _press(self, e):
        self._drag = (e.x_root, e.y_root, self.win.winfo_x(), self.win.winfo_y())

    def _dragmove(self, e):
        if not self._drag:
            return
        x0, y0, wx, wy = self._drag
        self.win.geometry('+%d+%d' % (wx + e.x_root - x0, wy + e.y_root - y0))

    # ---------- 小工具 ----------
    def _status(self, text, color=None):
        try:
            self.cv.itemconfig(self.status_item, text=text, fill=color or C_SUB)
        except Exception:
            pass

    def _set(self, entry, value):
        entry.delete(0, 'end')
        entry.insert(0, value or '')

    def _vals(self):
        return (self.e_url.get().strip(), self.e_key.get().strip(), self.e_model.get().strip())

    def _on_provider(self, name):
        for n, url, model in PROVIDERS:
            if n == name:
                if url:
                    self._set(self.e_url, url)
                if model:
                    self._set(self.e_model, model)
                return

    def _toggle_show(self):
        if self.e_key.cget('show'):
            self.e_key.config(show='')
            self.btn_show.config(text='隐藏')
        else:
            self.e_key.config(show='●')
            self.btn_show.config(text='显示')

    # ---------- 测试 / 保存 ----------
    def _test(self):
        if self.busy:
            return
        url, key, model = self._vals()
        if not url or not model:
            self._status('接口地址和模型不能为空', '#C06060')
            return
        self.busy = True
        self._status('正在测试连接…（最多 15 秒）', '#8A7A55')
        threading.Thread(target=self._test_worker, args=(url, key, model),
                         daemon=True).start()
        self.win.after(120, self._poll)

    def _test_worker(self, url, key, model):
        ok, msg = test_ai(url, key, model)
        self.q.put(('test', ok, msg))

    def _poll(self):
        if not self.alive:
            return
        try:
            _, ok, msg = self.q.get_nowait()
        except queue.Empty:
            self.win.after(120, self._poll)
            return
        self.busy = False
        if ok:
            self._status('连接成功！奶蛙说：%s' % msg, '#2E8B57')
        else:
            self._status('连接失败：%s' % msg, '#C06060')

    def _save(self):
        url, key, model = self._vals()
        if not url or not model:
            self._status('接口地址和模型不能为空', '#C06060')
            return
        ok, err = save_ai_config(url, key, model, True)
        if not ok:
            self._status('保存失败：%s' % err, '#C06060')
            return
        if AI_READY:
            self._status('已保存！AI 已开启（%s）' % AI_MODEL, '#2E8B57')
        else:
            self._status('已保存，但还没填 API Key，现在用的是本地小脑袋', '#C9812F')
        if self.on_saved:
            self.on_saved()
        self.win.after(800, self.close)

    def _disable(self):
        save_ai_config(AI_BASE_URL, AI_API_KEY, AI_MODEL, False)
        self._status('已关闭 AI，奶蛙用本地小脑袋陪你', C_SUB)
        if self.on_saved:
            self.on_saved()
        self.win.after(700, self.close)

    def close(self):
        self.alive = False
        try:
            self.win.destroy()
        except Exception:
            pass


# ============================================================
#  七、悬浮聊天框
# ============================================================
class ChatBox:
    W, H = 340, 470
    PAD, LH, GAP = 10, 20, 8

    def __init__(self, pet):
        self.pet = pet
        self.win = tk.Toplevel(pet.root)
        self.win.overrideredirect(True)
        self.win.attributes('-topmost', True)
        self.win.configure(bg=TRANSPARENT)
        self.win.attributes('-transparentcolor', TRANSPARENT)   # 圆角处透明

        self._place_near_pet()
        self.cv = tk.Canvas(self.win, width=self.W, height=self.H,
                            bg=TRANSPARENT, highlightthickness=0)
        self.cv.pack()

        self.font = tkfont.Font(family='Microsoft YaHei', size=10)
        self.font_s = tkfont.Font(family='Microsoft YaHei', size=9)

        self._draw_frame()

        # 聊天区
        self.chat_x, self.chat_y = 14, 62
        self.chat_w = self.W - 28
        self.chat_h = self.H - 62 - 66
        self.chat = tk.Canvas(self.win, bg=C_PANEL, highlightthickness=0)
        self.chat.place(x=self.chat_x, y=self.chat_y, width=self.chat_w, height=self.chat_h)

        # 输入区
        ey = self.H - 56
        self.entry = tk.Entry(self.win, bd=0, highlightthickness=1,
                              highlightbackground=C_PANEL_EDGE, highlightcolor=C_PANEL_EDGE,
                              bg=C_ENTRY_BG, fg=C_TXT, insertbackground=C_TXT,
                              font=('Microsoft YaHei', 10))
        self.entry.place(x=14, y=ey, width=self.W - 28 - 70, height=34)
        self.entry.bind('<Return>', lambda e: self.send())

        self.btn = tk.Button(self.win, text='发送', command=self.send,
                             bd=0, relief='flat', highlightthickness=0,
                             bg=C_BTN, activebackground=C_BTN_ACT, fg=C_TXT,
                             font=('Microsoft YaHei', 10), cursor='hand2')
        self.btn.place(x=self.W - 14 - 64, y=ey, width=64, height=34)

        # 状态
        self.alive = True
        self.messages = []
        self.scroll = 0.0
        self.items = []
        self.content_h = 0
        self.history = []            # 对话历史（发给 AI 用）
        self.ai_q = queue.Queue()    # 后台线程 -> 主线程 的结果队列
        self.waiting = False         # 是否正在等 AI 回复

        self.chat.bind('<MouseWheel>', self._on_wheel)
        self.cv.bind('<MouseWheel>', self._on_wheel)
        self.win.bind('<MouseWheel>', self._on_wheel)

        self._drag = None
        self.cv.bind('<Button-1>', self._press)
        self.cv.bind('<B1-Motion>', self._dragmove)

        self.say('frog', '嘿嘿，奶蛙来啦！今天怎么样呀？')
        self.entry.focus_set()

    # ---------- 外观 ----------
    def _draw_frame(self):
        cv = self.cv
        round_rect(cv, 6, 6, self.W - 6, self.H - 6, 20,
                   fill=C_PANEL, outline=C_PANEL_EDGE, width=2)
        # 标题栏
        round_rect(cv, 8, 8, self.W - 8, 56, 16, fill=C_HEAD, outline='')
        cv.create_rectangle(8, 40, self.W - 8, 58, fill=C_HEAD, outline='')
        cv.create_line(10, 58, self.W - 10, 58, fill=C_PANEL_EDGE)
        # 头像小圆点
        cv.create_oval(20, 22, 44, 46, fill='#F5BC3F', outline='#D08F1E', width=2)
        cv.create_oval(27, 29, 32, 34, fill='#1B1A12', outline='')
        cv.create_oval(34, 29, 39, 34, fill='#1B1A12', outline='')
        cv.create_text(54, 34, text='奶蛙', anchor='w',
                       font=('Microsoft YaHei', 12, 'bold'), fill=C_TXT)
        # 设置按钮（用画笔画一个齿轮，不依赖特殊字符字体）
        gx, gy = self.W - 72, 33
        cv.create_oval(gx - 13, gy - 13, gx + 13, gy + 13,
                       fill='#EFE3C8', outline='#C9B78A', tags='gear')
        cv.create_oval(gx - 5, gy - 5, gx + 5, gy + 5,
                       outline=C_TXT, width=2, tags='gear')
        for _a in range(0, 360, 60):
            _r = math.radians(_a)
            cv.create_line(gx + 5 * math.cos(_r), gy + 5 * math.sin(_r),
                           gx + 9 * math.cos(_r), gy + 9 * math.sin(_r),
                           fill=C_TXT, width=2, tags='gear')
        cv.tag_bind('gear', '<Button-1>', lambda e: self.open_settings())
        # 关闭按钮
        cv.create_oval(self.W - 48, 20, self.W - 20, 46,
                       fill='#FFC9C9', outline='#EFA0A0', tags='close')
        cv.create_text(self.W - 34, 33, text='×', fill='#8A3B3B',
                       font=('Microsoft YaHei', 12, 'bold'), tags='close')
        cv.tag_bind('close', '<Button-1>', lambda e: self.close())
        cv.create_text(16, 50, text='拖住这一条可以移动我～',
                       font=('Microsoft YaHei', 8), fill=C_SUB, anchor='w', tags='head')
        # 右下角显示当前用的是 AI 还是本地小脑袋
        self.status_item = cv.create_text(
            self.W - 16, 50,
            text=('● AI 已连接' if AI_READY else '○ 本地小脑袋'),
            font=('Microsoft YaHei', 8), anchor='e', tags='head',
            fill=('#3E8E4E' if AI_READY else C_SUB))

    def _place_near_pet(self):
        sw, sh = self.pet.root.winfo_screenwidth(), self.pet.root.winfo_screenheight()
        x = self.pet.wx - self.W - 12
        if x < 8:
            x = self.pet.wx + self.pet.w + 12
        if x + self.W > sw - 8:
            x = max(8, sw - self.W - 8)
        y = min(max(self.pet.wy + self.pet.h - self.H, 8), sh - self.H - 8)
        self.win.geometry('%dx%d+%d+%d' % (self.W, self.H, int(x), int(y)))

    # ---------- 拖动 ----------
    def _press(self, e):
        self._drag = (e.x_root, e.y_root, self.win.winfo_x(), self.win.winfo_y())

    def _dragmove(self, e):
        if not self._drag:
            return
        x0, y0, wx, wy = self._drag
        self.win.geometry('+%d+%d' % (wx + e.x_root - x0, wy + e.y_root - y0))

    # ---------- AI 设置 ----------
    def open_settings(self):
        """打开 AI 设置面板（在这里填 DeepSeek 的 Key，不用改任何文件）。"""
        s = getattr(self, 'settings', None)
        if s is not None and s.alive:
            try:
                s.win.lift()
                return
            except Exception:
                pass
        self.settings = SettingsBox(self.pet, on_saved=self.refresh_ai_status)

    def refresh_ai_status(self):
        """配置变化后刷新标题栏那个小标记。"""
        try:
            self.cv.itemconfig(self.status_item,
                               text=('● AI 已连接' if AI_READY else '○ 本地小脑袋'),
                               fill=('#3E8E4E' if AI_READY else C_SUB))
        except Exception:
            pass

    # ---------- 消息 ----------
    def _wrap(self, text, maxw):
        lines, cur = [], ''
        for ch in text:
            if ch == '\n':
                lines.append(cur); cur = ''
                continue
            if self.font.measure(cur + ch) <= maxw:
                cur += ch
            else:
                lines.append(cur); cur = ch
        if cur or not lines:
            lines.append(cur)
        return lines

    def say(self, who, text):
        self.messages.append([who, text])
        if len(self.messages) > 80:
            del self.messages[0]
        self._relayout(keep_bottom=True)

    def _relayout(self, keep_bottom=True):
        if not self.alive:
            return
        maxw = self.chat_w - 2 * self.PAD - 26
        items, y = [], 0
        for who, text in self.messages:
            lines = self._wrap(text, maxw)
            w = max(self.font.measure(l) for l in lines)
            bh = len(lines) * self.LH + 2 * self.PAD
            bw = min(self.chat_w - 16, w + 2 * self.PAD)
            items.append((who, lines, bw, bh, y))
            y += bh + self.GAP
        self.items = items
        self.content_h = y
        maxs = max(0.0, self.content_h - self.chat_h)
        self.scroll = maxs if keep_bottom else min(self.scroll, maxs)
        self._paint()

    def _paint(self):
        c = self.chat
        c.delete('all')
        for who, lines, bw, bh, y in self.items:
            top = y - self.scroll
            if top > self.chat_h or top + bh < 0:
                continue
            left = 8 if who == 'frog' else self.chat_w - 8 - bw
            fill = C_BUBBLE_F if who == 'frog' else C_BUBBLE_U
            round_rect(c, left, top, left + bw, top + bh, 12, fill=fill, outline='')
            for i, ln in enumerate(lines):
                c.create_text(left + self.PAD, top + self.PAD + i * self.LH,
                              text=ln, anchor='nw', font=self.font, fill=C_TXT)

    def _on_wheel(self, e):
        maxs = max(0.0, self.content_h - self.chat_h)
        self.scroll = min(maxs, max(0.0, self.scroll - e.delta / 120 * 30))
        self._paint()

    # ---------- 交互 ----------
    def send(self):
        text = self.entry.get().strip()
        if not text or self.waiting:
            return
        self.entry.delete(0, 'end')
        self.say('user', text)
        self.history.append({'role': 'user', 'content': text})
        self.messages.append(['frog', '奶蛙正在想…'])
        self._relayout(keep_bottom=True)
        if AI_READY:
            # 网络请求丢到后台线程，界面不卡
            self.waiting = True
            threading.Thread(target=self._ai_worker, daemon=True).start()
            self.win.after(100, self._poll_ai)
        else:
            self.win.after(420, lambda t=text: self._finish(frog_reply(t), t))

    def _ai_worker(self):
        """后台线程：只往队列里塞结果，绝不碰界面控件。"""
        try:
            self.ai_q.put(('ok', ai_chat(self.history)))
        except Exception as e:
            self.ai_q.put(('err', str(e)))

    def _poll_ai(self):
        """主线程轮询后台结果，安全地更新界面。"""
        if not self.alive:
            return
        try:
            kind, payload = self.ai_q.get_nowait()
        except queue.Empty:
            self.win.after(100, self._poll_ai)
            return
        self.waiting = False
        if kind == 'ok' and payload:
            self._finish(payload, None)
        else:
            # 连不上就退回内置短句，并在标题栏标出来
            try:
                self.cv.itemconfig(self.status_item, text='● AI 连接失败', fill='#C06060')
            except Exception:
                pass
            print('AI 调用失败：%s' % payload)
            t = self._last_user_text()
            self._finish(frog_reply(t), t)

    def _last_user_text(self):
        for m in reversed(self.history):
            if m.get('role') == 'user':
                return m.get('content', '')
        return ''

    def _finish(self, reply, text):
        if not self.alive:
            return
        if self.messages and self.messages[-1][0] == 'frog':
            self.messages[-1][1] = reply
        self.history.append({'role': 'assistant', 'content': reply})
        self._relayout(keep_bottom=True)
        # 被逗笑的话，顺手让奶蛙笑一下
        if text and any(w in text for w in ('笑', '哈', '哈哈')):
            self.pet.start_laugh(open_chat=False)

    def close(self):
        self.alive = False
        self.pet.chat = None
        try:
            self.win.destroy()
        except Exception:
            pass

    def set_visible(self, show):
        try:
            if show:
                self.win.deiconify()
            else:
                self.win.withdraw()
        except Exception:
            pass


# ============================================================
#  七、桌宠本体
# ============================================================
class MilkFrog:
    def __init__(self):
        self.root = tk.Tk()
        self.root.title('奶蛙')
        self.root.overrideredirect(True)             # 无边框
        self.root.attributes('-topmost', True)       # 置顶
        self.root.configure(bg=TRANSPARENT)
        self.root.attributes('-transparentcolor', TRANSPARENT)   # 透明 + 点击穿透

        self.sw = self.root.winfo_screenwidth()
        self.sh = self.root.winfo_screenheight()

        # 贴图
        self.imgs = {}
        for size, poses in SPR.items():
            self.imgs[size] = {p: tuple(tk.PhotoImage(data=d) for d in pair)
                               for p, pair in poses.items()}

        self.size_key = 'mid'
        self._apply_size()
        self.wx = self.sw - self.w - 60
        self.wy = self.sh - self.h - 70

        # 状态
        self.state = 'idle'          # idle / laugh / walk / pet(抚摸) / sing(唱歌)
        self.facing = 1              # 1 朝右（用镜像），-1 朝左（原图）
        self.vx = self.vy = 0.0
        self.idle_since = time.time()
        self.laugh_t0 = 0.0
        self.walk_until = 0.0
        self.paused = False
        self.dot = None
        self.chat = None
        self.press = None
        self.dragging = False
        # 抚摸 / 唱歌
        self.pet_t0 = 0.0
        self.pet_cache = {}          # 帧序号 -> PhotoImage（按需加载）
        self.sing_t0 = 0.0
        self.notes = []              # 唱歌时飘的音符

        # 音频
        self.audio_on = True
        self.next_cute_t = time.time() + random.uniform(CUTE_MIN_GAP, CUTE_MAX_GAP)

        self.canvas = tk.Canvas(self.root, width=self.w, height=self.h,
                                bg=TRANSPARENT, highlightthickness=0)
        self.canvas.pack()
        self.root.geometry('%dx%d+%d+%d' % (self.w, self.h, int(self.wx), int(self.wy)))

        self.canvas.bind('<Button-1>', self.on_press)
        self.canvas.bind('<B1-Motion>', self.on_drag)
        self.canvas.bind('<ButtonRelease-1>', self.on_release)
        self.canvas.bind('<Button-3>', self.on_menu)

        self._build_menu()
        self.tick()
        self.root.mainloop()

    # ---------- 尺寸 ----------
    def _apply_size(self):
        iw = self.imgs[self.size_key]['idle'][0].width()
        ih = self.imgs[self.size_key]['idle'][0].height()
        lw = self.imgs[self.size_key]['laugh'][0].width()
        self.w = max(iw, lw) + 24            # 两侧留抖动余量
        self.h = ih + 54                     # 上边留“哈!”的位置
        self.ground_y = self.h - 10          # 脚底对齐线（切换姿势时脚不动）

    # ---------- 主循环 ----------
    def tick(self):
        if self.root.state() == 'normal':
            now = time.time()
            self.update_state(now)
            self.draw()
        self.root.after(33, self.tick)       # ~30 FPS

    def update_state(self, now):
        if self.state == 'pet':
            # 抚摸动画放完就回待机
            if now - self.pet_t0 >= len(PET_FRAMES) / float(PET_FPS):
                self.state = 'idle'
                self.idle_since = now
            return

        if self.state == 'sing':
            if now - self.sing_t0 >= SING_DURATION:
                self.state = 'idle'
                self.idle_since = now
            return

        if self.state == 'laugh':
            if now - self.laugh_t0 >= LAUGH_DURATION:
                self.state = 'idle'
                self.idle_since = now
            return

        if self.state == 'idle':
            # 空闲随机播一句可爱音效
            if self.audio_on and now >= self.next_cute_t:
                play_sound(random.choice(SOUND_CUTE) if SOUND_CUTE else None, self.audio_on)
                self.next_cute_t = now + random.uniform(CUTE_MIN_GAP, CUTE_MAX_GAP)
            if now - self.idle_since >= IDLE_TIMEOUT:
                self.state = 'walk'
                self.walk_until = now + random.uniform(10, 20)
                self.pick_direction()
            return

        if self.state == 'walk':
            self.step_walk()
            if now >= self.walk_until:
                self.state = 'idle'
                self.idle_since = now
                self.next_cute_t = now + random.uniform(CUTE_MIN_GAP, CUTE_MAX_GAP)

    # ---------- 漫游 ----------
    def pick_direction(self):
        self.vx = random.uniform(1.0, 2.0) * random.choice([-1, 1])
        self.vy = random.uniform(0.3, 1.0) * random.choice([-1, 1])
        self.facing = 1 if self.vx >= 0 else -1

    def step_walk(self):
        if self.paused:
            return
        self.wx += self.vx
        self.wy += self.vy
        # 边界碰撞：自动转身，绝不跑出屏幕
        if self.wx <= 0:
            self.wx = 0; self.vx = abs(self.vx)
        elif self.wx + self.w >= self.sw:
            self.wx = self.sw - self.w; self.vx = -abs(self.vx)
        if self.wy <= 0:
            self.wy = 0; self.vy = abs(self.vy)
        elif self.wy + self.h >= self.sh:
            self.wy = self.sh - self.h; self.vy = -abs(self.vy)

        self.facing = 1 if self.vx >= 0 else -1
        if random.random() < 0.02:               # 偶尔随机改向
            self.vx = abs(self.vx) * random.choice([-1, 1])
            self.vy = random.uniform(0.3, 1.0) * random.choice([-1, 1])
            self.facing = 1 if self.vx >= 0 else -1
        self.root.geometry('+%d+%d' % (int(self.wx), int(self.wy)))

    # ---------- 鼠标 ----------
    def on_press(self, e):
        self.paused = True
        self.dragging = False
        self.press = (e.x_root, e.y_root, self.wx, self.wy)

    def on_drag(self, e):
        if self.press is None:
            return
        x0, y0, wx0, wy0 = self.press
        dx, dy = e.x_root - x0, e.y_root - y0
        if abs(dx) + abs(dy) > 5:
            self.dragging = True
        if self.dragging:
            self.wx, self.wy = wx0 + dx, wy0 + dy
            self.root.geometry('+%d+%d' % (int(self.wx), int(self.wy)))

    def on_release(self, e):
        self.paused = False
        was_drag = self.dragging
        self.dragging = False
        self.press = None
        if not was_drag:
            self.start_laugh(open_chat=True)     # 单击 = 大笑 + 弹聊天框
        else:
            self.state = 'idle'
            self.idle_since = time.time()

    def start_laugh(self, open_chat=True):
        """切换到大笑贴图 + 抖动 + 播放音效（+ 弹出聊天框）。"""
        self.state = 'laugh'
        self.laugh_t0 = time.time()
        play_sound(SOUND_LAUGH, self.audio_on)
        if open_chat:
            self.open_chat()

    # ---------- 抚摸 / 唱歌 ----------
    def start_pet(self):
        """右键「抚摸一下」：把你给的视频逐帧播放出来（背景已透明）。"""
        if not PET_FRAMES:
            return
        self.state = 'pet'
        self.pet_t0 = time.time()
        play_sound(SOUND_LAUGH, self.audio_on)      # 这段笑声就取自同一个视频

    def start_sing(self):
        """右键「唱首歌」：形象的贴图不变，只放歌 + 蹦蹦跳跳 + 飘音符。"""
        self.state = 'sing'
        self.sing_t0 = time.time()
        self.notes = []
        for k in range(SING_LOOPS):
            self.root.after(int(k * 2050),
                            lambda: play_sound(SOUND_SONG, self.audio_on)
                            if self.state == 'sing' else None)

    def _pet_image(self, i):
        """按需把某一帧解析成 PhotoImage 并缓存（161 帧不必启动时全解析）。"""
        img = self.pet_cache.get(i)
        if img is None:
            img = tk.PhotoImage(data=PET_FRAMES[i])
            self.pet_cache[i] = img
        return img

    def _note(self, c, x, y, s):
        """用画笔画一个小音符（不依赖字体里的 ♪ 符号）。"""
        r = 4.0 * s
        c.create_oval(x - r, y - r, x + r, y + r, fill='#E86A9A', outline='')
        c.create_line(x + r * 0.8, y, x + r * 0.8, y - 15 * s, fill='#E86A9A', width=2)
        c.create_line(x + r * 0.8, y - 15 * s, x + r * 0.8 + 7 * s, y - 11 * s,
                      fill='#E86A9A', width=2)

    def _draw_notes(self, c):
        """唱歌时头顶飘出的音符。"""
        top = self.ground_y - self.imgs[self.size_key]['idle'][0].height() - 6
        cx = self.w / 2
        while len(self.notes) < 3:
            self.notes.append([random.uniform(-36, 36), random.uniform(0, 0.6),
                               random.uniform(0.8, 1.25)])
        for n in self.notes:
            n[1] += 0.022
            if n[1] > 1.35:
                n[1] = 0.0
                n[0] = random.uniform(-36, 36)
                n[2] = random.uniform(0.8, 1.25)
            x = cx + n[0] + math.sin(n[1] * 6.0) * 7
            y = top - n[1] * 62
            self._note(c, x, y, n[2])

    # ---------- 聊天框 ----------
    def open_chat(self):
        if self.chat is None:
            self.chat = ChatBox(self)
        else:
            self.chat.win.lift()
            self.chat.win.attributes('-topmost', True)
            self.chat.set_visible(True)

    def open_ai_settings(self):
        """右键菜单里的「AI 设置…」。"""
        self.open_chat()
        if self.chat is not None:
            self.chat.open_settings()

    # ---------- 右键菜单 ----------
    def _build_menu(self):
        self.menu = tk.Menu(self.root, tearoff=0)
        self.menu.add_command(label='抚摸一下', command=self.start_pet)
        self.menu.add_command(label='唱首歌', command=self.start_sing)
        self.menu.add_separator()
        self.menu.add_command(label='打开聊天', command=self.open_chat)
        self.menu.add_command(label='AI 设置…', command=self.open_ai_settings)
        self.audio_var = tk.BooleanVar(value=True)
        self.menu.add_checkbutton(label='音效', variable=self.audio_var,
                                  command=self._toggle_audio)
        self.menu.add_command(label='试听音效',
                              command=lambda: play_sound(SOUND_LAUGH, True))
        self.menu.add_command(label='隐藏', command=self.hide)
        size_menu = tk.Menu(self.menu, tearoff=0)
        for label, key in (('小', 'small'), ('中', 'mid'), ('大', 'big')):
            size_menu.add_command(label=label, command=lambda k=key: self.set_size(k))
        self.menu.add_cascade(label='调整大小', menu=size_menu)
        self.menu.add_separator()
        self.menu.add_command(label='退出', command=self.quit)

    def _toggle_audio(self):
        self.audio_on = bool(self.audio_var.get())
        if self.audio_on:
            play_sound(SOUND_CUTE[0] if SOUND_CUTE else None, True)

    def on_menu(self, e):
        self.paused = True
        try:
            self.menu.tk_popup(e.x_root, e.y_root)
        finally:
            self.menu.grab_release()
            self.paused = False
            self.idle_since = time.time()

    def set_size(self, key):
        if key not in self.imgs:
            return
        cx = self.wx + self.w / 2
        cy = self.wy + self.h
        self.size_key = key
        self._apply_size()
        self.canvas.config(width=self.w, height=self.h)
        self.wx = min(max(cx - self.w / 2, 0), max(0, self.sw - self.w))
        self.wy = min(max(cy - self.h, 0), max(0, self.sh - self.h))
        self.root.geometry('%dx%d+%d+%d' % (self.w, self.h, int(self.wx), int(self.wy)))

    # ---------- 隐藏 / 恢复 ----------
    def hide(self):
        self.root.withdraw()
        if self.chat:
            self.chat.set_visible(False)
        self._show_dot()

    def _show_dot(self):
        if self.dot is not None:
            return
        dot = tk.Toplevel(self.root)
        dot.overrideredirect(True)
        dot.attributes('-topmost', True)
        dot.configure(bg=TRANSPARENT)
        dot.attributes('-transparentcolor', TRANSPARENT)
        mini = self.imgs['small']['idle'][0].subsample(4)
        dw, dh = mini.width(), mini.height()
        c = tk.Canvas(dot, width=dw + 8, height=dh + 8, bg=TRANSPARENT, highlightthickness=0)
        c.pack()
        c.create_image(4, 4, image=mini, anchor='nw')
        dot._mini = mini
        dot.geometry('+%d+%d' % (self.sw - dw - 40, self.sh - dh - 60))
        dot.bind('<Button-1>', lambda e: self._restore(dot))
        dot.bind('<Button-3>', lambda e: self._dot_menu(dot, e))
        self.dot = dot

    def _restore(self, dot):
        if self.dot is dot:
            dot.destroy()
            self.dot = None
        self.root.deiconify()
        self.state = 'idle'
        self.idle_since = time.time()
        self.paused = False
        if self.chat:
            self.chat.set_visible(True)

    def _dot_menu(self, dot, e):
        m = tk.Menu(dot, tearoff=0)
        m.add_command(label='退出', command=self.quit)
        m.tk_popup(e.x_root, e.y_root)

    def quit(self):
        try:
            self.root.destroy()
        except Exception:
            pass

    # ---------- 绘制 ----------
    def draw(self):
        c = self.canvas
        c.delete('all')
        now = time.time()

        dx = dy = 0.0
        squash = False
        pose = 'idle'

        # ---- 抚摸：直接逐帧播放视频（背景已抠成透明）----
        if self.state == 'pet' and PET_FRAMES:
            fi = int((now - self.pet_t0) * PET_FPS)
            fi = max(0, min(fi, len(PET_FRAMES) - 1))
            img = self._pet_image(fi)
            c.create_image(self.w / 2, self.ground_y, image=img, anchor='s')
            self._shown = img
            return

        if self.state == 'idle':
            breath = math.sin(now * TAU * 0.4)      # 缓慢呼吸
            sway = math.sin(now * TAU * 0.15)       # 轻轻晃动
            dx = sway * 3
            dy = breath * 2.2
            squash = breath < -0.35
        elif self.state == 'sing':
            # 唱歌：贴图不变，只跟着节奏蹦跳
            t = now - self.sing_t0
            dx = math.sin(t * 6.0) * 5
            dy = -abs(math.sin(t * 7.5)) * 9
            squash = int(t * 7) % 2 == 0
        elif self.state == 'laugh':
            pose = 'laugh'
            lt = now - self.laugh_t0
            k = max(0.0, 1 - lt / LAUGH_DURATION)
            dx = random.uniform(-1, 1) * 9 * k      # 身体抖动
            dy = random.uniform(-1, 1) * 6 * k - abs(math.sin(lt * 16)) * 6
        elif self.state == 'walk':
            dy = -abs(math.sin(now * 8)) * 5
            dx = math.sin(now * 8) * 2.5
            squash = math.sin(now * 8) > 0

        if pose == 'laugh':
            key = 'laugh'
        else:
            key = 'idle2' if squash else 'idle'
        idx = 1 if self.facing > 0 else 0        # 原图朝左，朝右用镜像
        img = self.imgs[self.size_key][key][idx]

        cx = self.w / 2 + dx
        c.create_image(cx, self.ground_y + dy, image=img, anchor='s')
        self._shown = img                        # 防止被垃圾回收

        if pose == 'laugh':
            c.create_text(cx, self.ground_y - self.imgs[self.size_key]['idle'][0].height() - 6,
                          text='哈!', fill='#FF5A5A',
                          font=('Microsoft YaHei', 16, 'bold'))

        if self.state == 'sing':
            self._draw_notes(c)


def main():
    if AI_READY:
        print('AI 已就绪：%s  模型 %s' % (AI_BASE_URL, AI_MODEL))
    else:
        print('=' * 56)
        print('提示：还没有配置 AI，奶蛙先用内置的小脑袋回答你。')
        print('想开 AI：在脚本同目录建 config.json，填 base_url / api_key / model；')
        print('或直接改本文件里的 AI_BASE_URL 和 AI_API_KEY。')
        print('=' * 56)
    if not SOUND_LAUGH and not SOUND_CUTE:
        print('警告：音效文件准备失败，将没有声音。')
    MilkFrog()


if __name__ == '__main__':
    main()
